('srd35_magic_holy_avenger','Holy avenger','magic_item',120630,120630,'This +2 cold iron longsword becomes a +5 holy cold iron longsword in the hands of a paladin.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-ii-armor-and-weapons.md','specific_weapons','{"source_file":"magic-items-ii-armor-and-weapons.md","source_table":"Table: Specific Weapons","market_price":"120,630 gp","roll_result":"— — 98–99","raw_table_row":["—","—","98–99","Holy avenger","120,630 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
